.fp{display:grid;grid-template-columns:minmax(250px,300px) 1fr;gap:18px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;color:#22262a;font-variant-numeric:tabular-nums}
.fp *{box-sizing:border-box}
.fp-controls{background:#f6f5f1;border:1px solid #e7e4dc;border-radius:14px;padding:14px 14px 12px}
.fp h3{margin:0 0 8px;font-size:14.5px;font-weight:650}
.fp-chips{display:flex;flex-wrap:wrap;gap:6px}
.fp-chip{all:unset;cursor:pointer;font-size:12.5px;line-height:1;padding:6px 10px;border-radius:999px;border:1px solid #dcd8cd;background:#fff;color:#454a4f;transition:background .15s,border-color .15s,color .15s}
.fp-chip:hover{border-color:#a9a497}
.fp-chip.is-on{background:#22262a;border-color:#22262a;color:#fff}
.fp-chip:focus-visible{outline:2px solid #3b78c4;outline-offset:2px}
.fp-small .fp-chip{font-size:12px;padding:5px 9px}
.fp-sliders{margin:12px 0 2px;display:flex;flex-direction:column;gap:6px}
.fp-slider{display:grid;grid-template-columns:100px 1fr 14px;align-items:center;gap:8px}
.fp-slider-name{display:flex;flex-direction:column;gap:1px;min-width:0}
.fp-slider-name b{display:flex;align-items:center;gap:6px;font-size:13px;font-weight:600}
.fp-slider-name i{width:8px;height:8px;border-radius:2px;background:var(--c);flex:none}
.fp-slider-name em{font-style:normal;color:#8a8e92;font-size:11px;padding-left:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fp-slider input{-webkit-appearance:none;appearance:none;width:100%;margin:0;height:20px;background:transparent;cursor:pointer}
.fp-slider input:focus-visible{outline:2px solid var(--c);outline-offset:2px;border-radius:4px}
.fp-slider input::-webkit-slider-runnable-track{height:6px;border-radius:3px;background:linear-gradient(to right,var(--c) var(--p),#dfdcd3 var(--p))}
.fp-slider input::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;margin-top:-5px;border-radius:50%;background:#fff;border:2.5px solid var(--c);box-shadow:0 1px 3px rgba(0,0,0,.18);transition:transform .12s}
.fp-slider input:active::-webkit-slider-thumb{transform:scale(1.15)}
.fp-slider input::-moz-range-track{height:6px;border-radius:3px;background:#dfdcd3}
.fp-slider input::-moz-range-progress{height:6px;border-radius:3px;background:var(--c)}
.fp-slider input::-moz-range-thumb{width:12px;height:12px;border-radius:50%;background:#fff;border:2.5px solid var(--c)}
.fp-slider strong{font-size:14px;color:var(--c);text-align:right}
.fp-group{margin-top:12px;display:flex;flex-direction:column;gap:6px}
.fp-group>span{font-size:12px;color:#6d7176;font-weight:600}
.fp-rank{min-width:0;display:flex;flex-direction:column}
.fp-rank header{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:10px}
.fp-rank header strong{font-size:15.5px;font-weight:650}
.fp-rank header p{margin:3px 0 0;font-size:12.5px;color:#7a7e83}
.fp-legend{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:4px 10px;font-size:11.5px;color:#5e6267;max-width:46%}
.fp-legend span{display:inline-flex;align-items:center;gap:4px;white-space:nowrap}
.fp-legend i{width:8px;height:8px;border-radius:2px}
.fp-empty{font-size:13px;color:#9a5a12;background:#fdf3e4;border-radius:8px;padding:7px 10px;margin:0 0 8px}
.fp-list{position:relative;transition:height .3s}
.fp-row{position:absolute;left:0;right:0;top:0;transition:transform .45s cubic-bezier(.2,.8,.2,1)}
.fp-row-main{all:unset;cursor:pointer;box-sizing:border-box;display:grid;grid-template-columns:26px minmax(150px,206px) 1fr 34px;align-items:center;gap:10px;width:100%;height:${X-6}px;padding:0 10px 0 6px;border-radius:10px;border:1px solid transparent;transition:background .15s,border-color .15s}
.fp-row-main:hover{background:#f7f7f5}
.fp-row-main:focus-visible{outline:2px solid #3b78c4}
.fp-row.is-top .fp-row-main{background:#f1f7f4;border-color:#cfe3d8}
.fp-row.is-open .fp-row-main{background:#f4f4f1;border-color:#e2e1db}
.fp-pos{font-size:15px;font-weight:700;color:#9a9ea3;text-align:center}
.fp-row.is-top .fp-pos{color:#2a8c82}
.fp-name{display:flex;flex-direction:column;gap:2px;min-width:0}
.fp-name b{font-size:13.5px;font-weight:620;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fp-name small{font-size:11.5px;color:#83878c;display:flex;align-items:center;gap:6px;white-space:nowrap;overflow:hidden}
.fp-badge{font-style:normal;font-size:10.5px;font-weight:650;color:#fff;background:#2a8c82;border-radius:4px;padding:2px 5px;line-height:1}
.fp-bar{display:flex;height:16px;border-radius:5px;background:#efefec;overflow:hidden}
.fp-bar span{height:100%;transition:width .45s cubic-bezier(.2,.8,.2,1)}
.fp-bar span+span{box-shadow:inset 1px 0 0 rgba(255,255,255,.65)}
.fp-out{width:100%!important;background:transparent!important;font-size:11px;color:#9a9ea3;line-height:16px;padding-left:8px}
.fp-score{font-size:16px;font-weight:700;text-align:right}
.fp-row.is-out{opacity:.5}
.fp-detail{display:grid;grid-template-columns:repeat(3,1fr);gap:4px 12px;padding:6px 10px 0 42px;height:${ee}px;font-size:11.5px}
.fp-detail span{display:grid;grid-template-columns:8px auto 28px 1fr;align-items:center;gap:6px;min-width:0}
.fp-detail span.is-off{opacity:.4}
.fp-detail i{width:8px;height:8px;border-radius:2px}
.fp-detail b{font-weight:600;white-space:nowrap}
.fp-detail strong{text-align:right}
.fp-detail em{font-style:normal;color:#7a7e83;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fp-rank footer{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:6px;font-size:12px;color:#8a8e92}
.fp-how-toggle{all:unset;cursor:pointer;font-size:12.5px;color:#3b78c4;font-weight:600;white-space:nowrap}
.fp-how-toggle:hover{text-decoration:underline}
.fp-how{margin:8px 0 0;padding:10px 14px 10px 30px;background:#f6f7f9;border-radius:10px;font-size:12.5px;line-height:1.6;color:#41464b}
@media (max-width:720px){.fp{grid-template-columns:1fr}.fp-legend{display:none}.fp-row-main{grid-template-columns:22px minmax(104px,130px) 1fr 30px;gap:8px}.fp-detail{grid-template-columns:repeat(2,1fr);padding-left:10px;height:${se}px}}
