.ss{border:1px solid #e6e4de;border-radius:14px;padding:14px 16px 12px;background:#fcfcfa;color:#22262a;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;font-variant-numeric:tabular-nums}
.ss header{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap}
.ss header strong{font-size:15px;font-weight:650}
.ss header p{margin:3px 0 0;font-size:12.5px;color:#7a7e83;max-width:520px}
.ss-switch{display:flex;align-items:center;gap:6px;font-size:12px;color:#6d7176}
.ss-switch button{all:unset;cursor:pointer;padding:5px 10px;border-radius:999px;border:1px solid #dcd8cd;background:#fff;color:#454a4f;font-size:12.5px}
.ss-switch button.is-on{background:#22262a;border-color:#22262a;color:#fff}
.ss-switch button:focus-visible{outline:2px solid #3b78c4;outline-offset:2px}
.ss svg{display:block;width:100%;height:auto;margin-top:6px;overflow:visible}
.ss-sweet{fill:#e9f4ee;transition:width .5s,height .5s}
.ss-sweet-label{font-size:12px;font-weight:600;fill:#2a8c82}
.ss-grid{stroke:#ecebe6}
.ss-median{stroke:#c7c4bb;stroke-dasharray:4 4}
.ss-tick{font-size:11px;fill:#8a8e92}
.ss-axis{font-size:12px;fill:#5e6267;font-weight:600}
.ss-pt{transition:transform .55s cubic-bezier(.2,.8,.2,1),opacity .2s;cursor:default}
.ss-pt circle{fill-opacity:.78;stroke:#fff;stroke-width:1.5}
.ss-pt.is-sweet circle{stroke:#22262a;stroke-width:2}
.ss-pt.is-dim{opacity:.35}
.ss-label{font-size:12.5px;font-weight:600;fill:#2d3135;paint-order:stroke;stroke:#fcfcfa;stroke-width:4px;stroke-linejoin:round}
.ss footer{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12px;color:#7a7e83;margin-top:4px}
.ss-groups{display:flex;gap:10px;flex-wrap:wrap}
.ss-groups span{display:inline-flex;align-items:center;gap:4px}
.ss-groups i{width:9px;height:9px;border-radius:50%}
@media (max-width:560px){.ss-label{font-size:16px}.ss-tick{font-size:14px}}
